export const t = (s) => {
  if (LOCALE === "en" || typeof s !== "string") return s;
  const row = DICT[s];
  const i = LOCALE_IDX[LOCALE];
  return (row && row[i]) || s;
};
// Parameterised: tp("{n} documents still needed", { n: 2 })
export const tp = (key, params) => {
  let out = t(key);
  if (params) Object.keys(params).forEach((k) => (out = out.split("{" + k + "}").join(String(params[k]))));
  return out;
};
